CREATE SEQUENCE "public"."events_category_id_seq" AS integer INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1 NO CYCLE;

CREATE TABLE "public"."categories" (
  "category_id" integer                NOT NULL DEFAULT nextval('public.events_category_id_seq'::regclass),
  "key"         character varying(255) NOT NULL,
  CONSTRAINT "events_pkey" PRIMARY KEY (category_id)
);

ALTER TABLE "public"."categories"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."itineraries_json" (
  "itinerary_json_id"  bigint                   GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."itineraries_json_id_seq") NOT NULL,
  "created_at"         timestamp with time zone NOT NULL DEFAULT now(),
  "itinerary_document" jsonb,
  CONSTRAINT "itineraries_json_pkey" PRIMARY KEY (itinerary_json_id)
);

ALTER TABLE "public"."itineraries_json"
  ENABLE ROW LEVEL SECURITY;

ALTER SEQUENCE "public"."events_category_id_seq" OWNED BY "public"."categories"."category_id";

CREATE POLICY "Give users authenticated access to folder 13itpk1_0" ON "storage"."objects"
  FOR INSERT
  TO "authenticated"
  WITH CHECK (((bucket_id = 'Photos'::text) AND (auth.role() = 'authenticated'::text)));

